15	    public CatalogServiceTests()
16	    {
17	        _connection = new SqliteConnection("Data Source=:memory:");
18	        _connection.Open();
19	        // SQLite's built-in lower() only folds ASCII a-z by default, unlike SQL Server's
20	        // collation-aware LOWER(). Override it so the test provider matches production
21	        // behavior for non-ASCII input (e.g. German umlauts) instead of silently diverging.
22	        _connection.CreateFunction<string?, string?>("lower", s => s?.ToLowerInvariant());
23	
24	        var options = new DbContextOptionsBuilder<AppDbContext>()
25	            .UseSqlite(_connection)
26	            .Options;
27	
28	        _context = new AppDbContext(options);
29	        _context.Database.EnsureCreated();
30	        _service = new CatalogService(_context);
31	
32	        SeedProducts();
