204	    private void SeedProductsWithOffers()
205	    {
206	        var category = new Category { Id = "CP", Name = "Preiskategorie" };
207	        var subcategory = new Subcategory { Id = "SP1", Name = "Preisunterkategorie", CategoryId = "CP" };
