1	import { Component, computed, inject, signal } from '@angular/core';
2	
3	import { CatalogApiService } from '../catalog-api.service';
4	import { CategoryNav } from '../category-nav/category-nav';
5	import { CategorySummary, ProductSummary } from '../product.model';
6	import { SearchBox } from '../search-box/search-box';
7	import { SortSelect, SortSelection } from '../sort-select/sort-select';
8	
9	@Component({
10	  selector: 'app-product-list',
11	  imports: [CategoryNav, SortSelect, SearchBox],
12	  templateUrl: './product-list.html'
13	})
14	export class ProductList {
15	  private catalogApi = inject(CatalogApiService);
16	
17	  protected readonly page = signal(1);
18	  protected readonly items = signal<ProductSummary[]>([]);
19	  protected readonly totalCount = signal(0);
20	  protected readonly loading = signal(false);
21	  protected readonly pageSize = signal(0);
22	  protected readonly categories = signal<CategorySummary[]>([]);
23	  protected readonly selectedCategoryId = signal<string | null>(null);
24	  protected readonly selectedSubcategoryId = signal<string | null>(null);
25	  protected readonly selectedSortBy = signal<string | null>(null);
26	  protected readonly selectedSortDirection = signal<string | null>(null);
27	  protected readonly selectedSearch = signal<string | null>(null);
28	
29	  protected readonly totalPages = computed(() => Math.max(1, Math.ceil(this.totalCount() / (this.pageSize() || 1))));
30	  protected readonly hasPreviousPage = computed(() => this.page() > 1);
31	  protected readonly hasNextPage = computed(() => this.page() * this.pageSize() < this.totalCount());
32	
33	  constructor() {
34	    this.loadPage(this.page());
35	    this.loadCategories();
36	  }
37	
38	  protected goToPreviousPage(): void {
39	    if (this.hasPreviousPage() && !this.loading()) {
40	      this.loadPage(this.page() - 1);
41	    }
42	  }
43	
44	  protected goToNextPage(): void {
45	    if (this.hasNextPage() && !this.loading()) {
46	      this.loadPage(this.page() + 1);
47	    }
48	  }
49	
50	  protected selectCategory(categoryId: string): void {
51	    if (this.loading()) {
52	      return;
53	    }
54	    this.selectedCategoryId.set(categoryId);
55	    this.selectedSubcategoryId.set(null);
56	    this.loadPage(1);
57	  }
58	
59	  protected selectSubcategory(subcategoryId: string): void {
60	    if (this.loading()) {
61	      return;
62	    }
63	    this.selectedCategoryId.set(null);
64	    this.selectedSubcategoryId.set(subcategoryId);
65	    this.loadPage(1);
66	  }
67	
68	  protected clearSelection(): void {
69	    if (this.loading()) {
70	      return;
71	    }
72	    this.selectedCategoryId.set(null);
73	    this.selectedSubcategoryId.set(null);
74	    this.loadPage(1);
75	  }
76	
77	  protected onSortChanged(sort: SortSelection | null): void {
78	    if (this.loading()) {
79	      return;
80	    }
81	    this.selectedSortBy.set(sort?.sortBy ?? null);
82	    this.selectedSortDirection.set(sort?.sortDirection ?? null);
83	    this.loadPage(1);
84	  }
85	
86	  protected onSearchChanged(search: string | null): void {
87	    if (this.loading()) {
88	      return;
89	    }
90	    this.selectedSearch.set(search);
91	    this.loadPage(1);
92	  }
93	
94	  private loadCategories(): void {
95	    this.catalogApi.getCategories().subscribe({
96	      next: (categories) => {
97	        this.categories.set(categories);
98	      },
99	      error: () => {
100	        this.categories.set([]);
101	      }
102	    });
103	  }
104	
105	  private loadPage(page: number): void {
106	    this.loading.set(true);
107	    this.catalogApi
108	      .getProducts(
109	        page,
110	        this.selectedCategoryId(),
111	        this.selectedSubcategoryId(),
112	        this.selectedSortBy(),
113	        this.selectedSortDirection(),
114	        this.selectedSearch()
115	      )
116	      .subscribe({
117	        next: (response) => {
118	          this.page.set(response.page);
119	          this.items.set(response.items);
120	          this.totalCount.set(response.totalCount);
121	          this.pageSize.set(response.pageSize);
122	          this.loading.set(false);
123	        },
124	        error: () => {
125	          this.loading.set(false);
126	        }
127	      });
128	  }
129	}
