    @Component({
      selector: 'app-property-filters',
      templateUrl: './property-filters.html'
    })
    export class PropertyFilters {
      properties = input.required<string[]>();
      disabled = input(false);
      filtersChanged = output<Record<string, string> | null>();

      protected onSubmit(formEl: HTMLFormElement): void {
        const formData = new FormData(formEl);
        const filters: Record<string, string> = {};
        for (const name of this.properties()) {
          const value = (formData.get(name) as string | null)?.trim();
          if (value) {
            filters[name] = value;
          }
        }
        this.filtersChanged.emit(Object.keys(filters).length > 0 ? filters : null);
      }
    }
    ```
    `FormData` liest die aktuell im DOM gerenderten Eingabefelder über deren `name`-Attribut aus — löst das Problem, eine dynamische, pro Unterkategorie unterschiedliche Anzahl von Eingabefeldern ohne `ViewChildren`-Boilerplate einzusammeln. `jsdom` (Vitest-Testumgebung dieses Projekts) unterstützt `FormData` nativ, kein zusätzliches Polyfill nötig.
